import sys
from collections import deque

def solve():
    input = sys.stdin.readline
    H, W, T = map(int, input().split())
    grid = [list(input().strip()) for _ in range(H)]

    candies = []
    start = goal = None
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'G':
                goal = (i, j)
            elif grid[i][j] == 'o':
                candies.append((i, j))

    n = len(candies)
    points = [start] + candies + [goal]
    N = n + 2  # start + candies + goal

    # BFS from each point
    INF = 10**9
    dist = [[INF]*N for _ in range(N)]

    dirs = [(1,0),(-1,0),(0,1),(0,-1)]

    for idx, (sx, sy) in enumerate(points):
        d = [[-1]*W for _ in range(H)]
        d[sx][sy] = 0
        q = deque()
        q.append((sx, sy))
        while q:
            x, y = q.popleft()
            for dx, dy in dirs:
                nx, ny = x+dx, y+dy
                if 0 <= nx < H and 0 <= ny < W and grid[nx][ny] != '#' and d[nx][ny] == -1:
                    d[nx][ny] = d[x][y] + 1
                    q.append((nx, ny))
        for jdx, (tx, ty) in enumerate(points):
            if d[tx][ty] != -1:
                dist[idx][jdx] = d[tx][ty]

    # Check if start can reach goal
    if dist[0][n+1] > T:
        print(-1)
        return

    # DP over subsets
    # dp[mask][i] = min moves to start at S, visit candies in mask, end at candy i (0-indexed candies)
    # candies indices in points: 1..n
    size = 1 << n
    dp = [[INF]*n for _ in range(size)]

    # init: from start to each candy
    for i in range(n):
        if dist[0][i+1] < INF:
            dp[1<<i][i] = dist[0][i+1]

    ans = 0  # 0 candies possible if start->goal within T

    for mask in range(size):
        for i in range(n):
            if dp[mask][i] == INF:
                continue
            # try to go to goal
            if dp[mask][i] + dist[i+1][n+1] <= T:
                ans = max(ans, bin(mask).count("1"))
            # try to add more candies
            for j in range(n):
                if not (mask & (1<<j)):
                    nmask = mask | (1<<j)
                    nd = dp[mask][i] + dist[i+1][j+1]
                    if nd < dp[nmask][j]:
                        dp[nmask][j] = nd

    print(ans)

if __name__ == "__main__":
    solve()

